import { router } from 'expo-router';
import { StatusBar } from 'expo-status-bar';
import { useState } from 'react';
import { StyleSheet, useWindowDimensions, View } from 'react-native';
import { useReducedMotion } from 'react-native-reanimated';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { NightColors } from '@/constants/theme';
import { AGREEMENT_HERO_HEIGHT, AgreementHero } from '@/components/agreement/agreement-hero';
import { Consent } from '@/components/agreement/consent';
import { SlideCarousel } from '@/components/agreement/slide-carousel';

/** The design was drawn for a 390 × 844 pt phone; positions scale from that. */
const DESIGN_HEIGHT = 844;
/** Where the hero starts in the design (pt from the top). */
const HERO_TOP = 120;
/** Gap between the hero and the slides in the design. */
const SLIDES_GAP = 53;
/**
 * Height the slides, dots and bottom block need no matter what (pt).
 * Whatever is left over is shared by the hero and its gaps.
 */
const FIXED_HEIGHT = 306;

/**
 * Agreement screen ("/agreement"), shown after the welcome screen, from the
 * Afterdream Agreement design: the lime logo rises out of a line above its own
 * reflection, three lines about the app take turns, and "Continue with Apple"
 * unlocks once the Terms and Privacy Policy are accepted.
 */
export default function AgreementScreen() {
  const { height } = useWindowDimensions();
  const insets = useSafeAreaInsets();
  const reduceMotion = useReducedMotion();

  const [agreed, setAgreed] = useState(false);
  const [signing, setSigning] = useState(false);
  function handleContinue() {
    if (!agreed) return;
    setSigning(true);
    // There is no Sign in with Apple yet, so this goes straight to the "You're in" screen.
    // `replace` (not `push`) so "back" doesn't return here.
    router.replace('/welcome-in');
  }

  // Shrink the hero on short phones so the slides never run into the button.
  const scale = Math.min(1, Math.max(0.6, (height - FIXED_HEIGHT) / (HERO_TOP + AGREEMENT_HERO_HEIGHT + SLIDES_GAP)));
  const heroTop = Math.max(insets.top + 8, height * (HERO_TOP / DESIGN_HEIGHT) * scale);
  const slidesTop = heroTop + (AGREEMENT_HERO_HEIGHT + SLIDES_GAP) * scale;

  return (
    <View style={styles.screen}>
      <StatusBar style="light" />

      <View style={[styles.hero, { top: heroTop }]}>
        <AgreementHero scale={scale} reduceMotion={reduceMotion} />
      </View>

      <View style={[styles.slides, { top: slidesTop }]}>
        <SlideCarousel reduceMotion={reduceMotion} />
      </View>

      <View style={[styles.consent, { bottom: Math.max(insets.bottom + 6, 24) }]}>
        <Consent
          agreed={agreed}
          onToggle={() => setAgreed((a) => !a)}
          signing={signing}
          onContinue={handleContinue}
          reduceMotion={reduceMotion}
        />
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: {
    flex: 1,
    backgroundColor: NightColors.background,
  },
  hero: {
    position: 'absolute',
    left: 0,
    right: 0,
  },
  slides: {
    position: 'absolute',
    left: 32,
    right: 32,
  },
  consent: {
    position: 'absolute',
    left: 24,
    right: 24,
  },
});
=== SHEET
import { Pressable, StyleSheet, Text, View } from 'react-native';
import Animated from 'react-native-reanimated';
import Svg, { Path } from 'react-native-svg';

import { BrandColors, BrandFonts, NightColors } from '@/constants/theme';

type SignInSheetProps = {
  agreed: boolean;
  onToggle: () => void;
  signing: boolean;
  onContinue: () => void;
  /** Space kept clear at the bottom (home indicator). */
  bottomPadding: number;
  reduceMotion: boolean;
};

/** Apple logo from the design (17 × 20 viewBox). */
const APPLE_PATH =
  'M14.1 10.6c0-2.6 2.1-3.8 2.2-3.9-1.2-1.8-3.1-2-3.7-2-1.6-.2-3.1.9-3.9.9-.8 0-2-.9-3.4-.9-1.7 0-3.3 1-4.2 2.6-1.8 3.1-.5 7.7 1.3 10.2.9 1.2 1.9 2.6 3.2 2.6 1.3-.1 1.8-.8 3.3-.8 1.6 0 2 .8 3.4.8 1.4 0 2.3-1.3 3.1-2.5 1-1.4 1.4-2.8 1.4-2.9 0 0-2.7-1-2.7-4.1zM11.6 3c.7-.9 1.2-2 1-3.2-1 0-2.3.7-3 1.6-.7.8-1.2 2-1.1 3.1 1.2.1 2.3-.6 3.1-1.5z';

/** The check pops in slightly too big, then settles. */
const CHECK_POP = {
  '0%': { transform: [{ scale: 0.4 }] },
  '60%': { transform: [{ scale: 1.15 }] },
  '100%': { transform: [{ scale: 1 }] },
};

/** Grey of the empty checkbox and the locked button text. */
const MUTED = NightColors.buttonOffText;

/**
 * Black sheet at the bottom of the Welcome Ghost screen: "I agree to the Terms…"
 * round checkbox, and "Continue with Apple", which turns white once agreed.
 */
export function SignInSheet({ agreed, onToggle, signing, onContinue, bottomPadding, reduceMotion }: SignInSheetProps) {
  const motion = reduceMotion ? 0 : 1;
  const buttonText = agreed ? '#000000' : MUTED;
  const colorTransition = {
    transitionProperty: 'color' as const,
    transitionDuration: 350 * motion,
    transitionTimingFunction: 'ease' as const,
  };

  return (
    <View style={[styles.sheet, { paddingBottom: bottomPadding }]}>
      <Pressable
        accessibilityRole="checkbox"
        accessibilityState={{ checked: agreed }}
        onPress={onToggle}
        style={styles.row}>
        <Animated.View
          style={[
            styles.box,
            {
              borderColor: agreed ? BrandColors.lime : MUTED,
              backgroundColor: agreed ? BrandColors.lime : 'transparent',
              transitionProperty: ['borderColor', 'backgroundColor'],
              transitionDuration: 250 * motion,
              transitionTimingFunction: 'ease',
            },
          ]}>
          {agreed && (
            <Animated.View
              style={{ animationName: CHECK_POP, animationDuration: 350 * motion, animationTimingFunction: 'ease' }}>
              <Svg width={13} height={13} viewBox="0 0 14 14">
                <Path
                  d="M2.5 7.5l3 3 6-7"
                  fill="none"
                  stroke={BrandColors.ink}
                  strokeWidth={2.4}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </Svg>
            </Animated.View>
          )}
        </Animated.View>
        {/* TODO: link these once the Terms of Service and Privacy Policy pages exist. */}
        <Text style={styles.label}>
          I agree to the <Text style={styles.link}>Terms</Text> and <Text style={styles.link}>Privacy Policy</Text>
        </Text>
      </Pressable>

      <Pressable
        accessibilityRole="button"
        accessibilityState={{ disabled: !agreed || signing }}
        onPress={onContinue}
        disabled={!agreed || signing}
        style={({ pressed }) => [pressed && styles.pressed]}>
        <Animated.View
          style={[
            styles.button,
            {
              backgroundColor: agreed ? '#FFFFFF' : NightColors.buttonOff,
              transitionProperty: 'backgroundColor',
              transitionDuration: 350 * motion,
              transitionTimingFunction: 'ease',
            },
          ]}>
          <Svg width={17} height={20} viewBox="0 0 17 20">
            <Path d={APPLE_PATH} fill={buttonText} />
          </Svg>
          <Animated.Text style={[styles.buttonText, { color: buttonText }, colorTransition]}>
            {signing ? 'Signing in…' : 'Continue with Apple'}
          </Animated.Text>
        </Animated.View>
      </Pressable>
