/** The check pops in slightly too big, then settles. */
const CHECK_POP = {
  '0%': { transform: [{ scale: 0.4 }] },
  '60%': { transform: [{ scale: 1.15 }] },
  '100%': { transform: [{ scale: 1 }] },
};

/** Grey of the empty checkbox and the locked button text. */
