        />
        <Stack.Screen
          name="welcome-in"
          options={{ headerShown: false, animation: 'fade', animationDuration: QUICK_FADE_MS, contentStyle: { backgroundColor: NightColors.background } }}
        />
        <Stack.Screen
          name="onboarding-name"
          options={{ headerShown: false, animation: 'fade', animationDuration: QUICK_FADE_MS, contentStyle: { backgroundColor: NightColors.background } }}
        />
        <Stack.Screen
          name="onboarding-birthday"
          options={{ headerShown: false, animation: 'fade', animationDuration: QUICK_FADE_MS, contentStyle: { backgroundColor: NightColors.background } }}
        />
        <Stack.Screen
          name="onboarding-gender"
          options={{ headerShown: false, animation: 'fade', animationDuration: QUICK_FADE_MS, contentStyle: { backgroundColor: NightColors.background } }}
